<span class="st-end">浅倉さんが「ずるくないですか」と言うと、鹿沼は首を振った。「電卓の使い方を変えただけで、解いている中身は同じです」。そして時計を指した。「<b>10分の作業を3分にする道具を、本番で使わない理由がありますか</b>。省力化のテクニックではなく、前提条件だと思ってください」。浅倉さんはその日から、練習も全部このモードで通すことにした。</span></div></div><!--/story-->
<h4>4. 試験で使える電卓のルール</h4>
<ul>
