<p class="muted small">この講義で身につくこと ── ①代理の三面関係を図で描けるようになる ②無権代理の相手方が持つ3つの武器を要件つきで使い分けられる ③「無権代理と相続」の4パターンを信義則から導ける ④表見代理3類型と重畳適用を整理できる</p>

