<p class="muted small">この講義で身につくこと ── ①3条業務の全体像を「表示登記の周辺」という軸で描ける ②筆界特定の代理とADR代理で要件が違う理由を説明できる ③資格・欠格事由と非調査士行為の禁止を正確に扱える</p>

