<!--story--><div class="story"><div class="st-case">「申請してから登記が終わるまで、中では何が起きているんですか」。関口さんに、鹿沼は流れを書き出した。「<b>受付、調査、そして完了か却下</b>。その途中で、申請人が自分から取り下げることもできます」
