<span class="st-out"><b>こうなる</b>図面は<b>各階の形を公示するもの</b>で、省略すると何階の図なのか分からなくなる。ほかの細部として、<b>地下のみの建物は地下1階の形状を朱書きする</b>。<b>電子申請で送信する各階平面図には、作成の年月日と、申請人及び作成者の氏名又は名称を記録する</b>。</span>
